import { describe, expect, it } from 'vitest'
import fixture from './fixtures/recording-delivery.json'
import { parseRecordingDelivery, recordingReceiptLabel } from '../src/recording-delivery.js'
import { recordingFileMatchesDay, recordingFileAudioDuration, recordingFileDisplayEnd, recordingFileExpectedBytes, recordingFileStatusLabel } from '../src/client/recordings/recording-day-files.js'
import type { PublicRecordingImportOwnerTask } from '../src/recording-import-shared.js'

// Generated by Audio's TestRecordingDeliveryWireContract, consumed unchanged by iOS.
describe('Audio receipt contract', () => {
  it('keeps received bytes, capture ending and completeness independent', () => {
    const waiting = parseRecordingDelivery(fixture.awaiting_end)!
    expect(waiting.receivedBytes).toBe(3400)
    expect(waiting.expectedBytes).toBeNull()
    expect(recordingReceiptLabel(waiting)).toContain('录音结束信息待确认')
    const complete = parseRecordingDelivery(fixture.complete)!
    expect(complete.coverage).toBe('complete')
    expect(complete.durationFinal).toBe(false)
    expect(complete.audioDurationMs).toBe(840)
    expect(complete.displayEndAt! - complete.captureStartAt!).toBe(60000)
    expect(parseRecordingDelivery(fixture.incomplete)!.coverage).toBe('interrupted')
  })
  it('keeps unknown distinct from known zero, and rejects malformed facts', () => {
    expect(parseRecordingDelivery(fixture.unknown)!.audioDurationMs).toBeNull()
    expect(parseRecordingDelivery(fixture.empty)!.audioDurationMs).toBe(0)
    expect(parseRecordingDelivery(fixture.empty)!.expectedBytes).toBe(0)
    expect(() => parseRecordingDelivery({ ...fixture.complete, received_bytes: -1 })).toThrow()
    expect(() => parseRecordingDelivery({ ...fixture.complete, end_received: 'yes' })).toThrow()
  })
  it('projects the same facts in the daily files view without fabricating completion', () => {
    const file = { delivery: parseRecordingDelivery(fixture.awaiting_end), durationMillis: 0, endAtMillis: 10,
      fileSize: 3400, status: 'accepted', statusDetail: '已接收 1 个文件 · 录音结束信息待确认' } as PublicRecordingImportOwnerTask
    expect(recordingFileAudioDuration(file)).toBe(840)
    expect(recordingFileDisplayEnd(file)).toBeNull()
    expect(recordingFileExpectedBytes(file)).toBeNull()
    expect(recordingFileStatusLabel(file)).toContain('待确认')
  })
})

it('includes a capture spanning midnight even when its effective audio lasts less than a second', () => {
  const nextDay = new Date(2026, 10, 16).getTime()
  const delivery = { ...parseRecordingDelivery(fixture.complete)!, displayEndAt: nextDay + 30000 }
  const file = { delivery, startAtMillis: nextDay - 30000, endAtMillis: nextDay - 29160 } as PublicRecordingImportOwnerTask
  expect(recordingFileMatchesDay(file, nextDay, 'recorded')).toBe(true)
})
